import{_ as e,c as a,o as s,b0 as t}from"./chunks/framework.BGmB-84D.js";const k=JSON.parse('{"title":"use boinc","description":"","frontmatter":{"date":"2025-9-1","title":"use boinc"},"headers":[],"relativePath":"learning/use-boinc.md","filePath":"learning/use-boinc.md"}'),n={name:"learning/use-boinc.md"};function r(l,i,h,o,c,d){return s(),a("div",null,[...i[0]||(i[0]=[t('<h1 id="什么是boinc" tabindex="-1">什么是boinc <a class="header-anchor" href="#什么是boinc" aria-label="Permalink to “什么是boinc”">​</a></h1><p><img src="https://boinc.berkeley.edu/logo/boinc_logo.png" alt="logo of boinc"></p><ul><li><p>BOINC lets you help cutting-edge science research using your computer. The BOINC app, running on your computer, downloads scientific computing jobs and runs them invisibly in the background. It&#39;s easy and safe.</p></li><li><p>About 30 science projects use BOINC. They investigate diseases, study climate change, discover pulsars, and do many other types of scientific research.</p></li><li><p>The BOINC and Science United projects are located at the University of California, Berkeley and are supported by the National Science Foundation.</p></li></ul><h1 id="为什么我想跑boinc" tabindex="-1">为什么我想跑boinc <a class="header-anchor" href="#为什么我想跑boinc" aria-label="Permalink to “为什么我想跑boinc”">​</a></h1><p>我之前买了一个服务器，平时负载不大，功率大概200w，&quot;性价比&quot;不是很高，闲置的算力不如给人类社区做点贡献（或者挖矿？）。</p><h1 id="各种安装方案" tabindex="-1">各种安装方案 <a class="header-anchor" href="#各种安装方案" aria-label="Permalink to “各种安装方案”">​</a></h1><h2 id="_1-裸机直装" tabindex="-1">1. 裸机直装 <a class="header-anchor" href="#_1-裸机直装" aria-label="Permalink to “1. 裸机直装”">​</a></h2><p>优点是可以利用显卡，archlinux的wiki说明也很详细。但是如果你在自己的账号运行，下载的各种东西会把你的home弄乱。</p><h2 id="_2-docker" tabindex="-1">2. docker <a class="header-anchor" href="#_2-docker" aria-label="Permalink to “2. docker”">​</a></h2><p>优点开箱即用，隔离性更好。我选docker <a href="https://github.com/k88936/boinc" target="_blank" rel="noreferrer">demo</a></p><h1 id="运行" tabindex="-1">运行 <a class="header-anchor" href="#运行" aria-label="Permalink to “运行”">​</a></h1><h2 id="使用命令行" tabindex="-1">使用命令行 <a class="header-anchor" href="#使用命令行" aria-label="Permalink to “使用命令行”">​</a></h2><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boinccmd</span></span></code></pre></div><h2 id="添加账户管理-science-united" tabindex="-1">添加账户管理 science united <a class="header-anchor" href="#添加账户管理-science-united" aria-label="Permalink to “添加账户管理 science united”">​</a></h2><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boinccmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --acct_mgr</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> attach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> name</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> passwd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  attach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> account</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> manager</span></span></code></pre></div><h2 id="添加-world-community-grid" tabindex="-1">添加 world community grid <a class="header-anchor" href="#添加-world-community-grid" aria-label="Permalink to “添加 world community grid”">​</a></h2><div class="language-shell"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">boinccmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project_attach</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> auth</span></span></code></pre></div><p><a href="https://www.worldcommunitygrid.org/help/topic.s?shortName=boinc" target="_blank" rel="noreferrer">reference</a><a href="https://www.worldcommunitygrid.org/ms/viewMyProfile.do" target="_blank" rel="noreferrer">where is auth</a></p>',18)])])}const g=e(n,[["render",r]]);export{k as __pageData,g as default};
